func step(t *testing.T, m Model, msg tea.Msg) (Model, tea.Cmd) {
	t.Helper()
	next, cmd := m.Update(msg)
	updated, ok := next.(Model)
	if !ok {
		t.Fatalf("Update() returned %T, want workspaces.Model", next)
	}
	return updated, cmd
}

// rowNames returns the Name cell of every table row.
