diff --git a/internal/ui/workspaces/sync.go b/internal/ui/workspaces/sync.go
index 7ffdafd..f51cafe 100644
--- a/internal/ui/workspaces/sync.go
+++ b/internal/ui/workspaces/sync.go
@@ -25,18 +25,29 @@ import (
 // git repository syncs itself, a plain directory syncs every repository nested
 // under it, anything else does nothing.

-// busyMessage is what both actions say when the other one holds the repository.
-// One message rather than two, because the user's next move is the same either
-// way: wait.
-const busyMessage = "Already busy — a scan or sync is running here"
+// busyMessage is what every action says when another one holds the repository.
+// One message rather than three, because the user's next move is the same
+// whichever holds it: wait.
+const busyMessage = "Already busy — a scan, sync or delete is running here"

-// busy reports whether a repository is already being scanned or synced.
+// busy reports whether a repository is already being scanned, synced or
+// deleted.
 //
 // A scan reads the working tree while a fast-forward rewrites it; running both
 // at once is a race whose visible result is a report describing a tree that no
-// longer exists. Whichever started first keeps the repository.
+// longer exists. A delete is worse on both counts — it takes the tree away
+// from under either of them, and re-issuing it fails on a path that is already
+// gone. Whichever started first keeps the repository.
 func (m Model) busy(path string) bool {
-	return m.scanningPaths[path] || m.syncingPaths[path]
+	return m.scanningPaths[path] || m.syncingPaths[path] || m.deletingPaths[path]
+}
+
+// anyBusy reports whether any operation is running at all. It is what decides
+// whether the spinner chain keeps going, and it is one function rather than
+// the predicate written out at each site — a fourth map would otherwise have
+// to be remembered in three places.
+func (m Model) anyBusy() bool {
+	return len(m.scanningPaths) > 0 || len(m.syncingPaths) > 0 || len(m.deletingPaths) > 0
 }

 // startSync syncs the row under the cursor, or everything beneath it.
diff --git a/internal/ui/workspaces/update.go b/internal/ui/workspaces/update.go
index 3a417b0..e059ded 100644
--- a/internal/ui/workspaces/update.go
+++ b/internal/ui/workspaces/update.go
@@ -2,6 +2,7 @@ package workspaces

 import (
 	"fmt"
+	"log"
 	"os"
 	"path/filepath"

@@ -119,7 +120,7 @@ func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 		return m, nil

 	case spinner.TickMsg:
-		if len(m.scanningPaths) > 0 || len(m.syncingPaths) > 0 {
+		if m.anyBusy() {
 			var cmd tea.Cmd
 			m.spinner, cmd = m.spinner.Update(msg)
 			m.spinnerFrameIdx = (m.spinnerFrameIdx + 1) % len(spinner.Dot.Frames)
@@ -275,7 +276,7 @@ func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
 // tick has arrived doubles the chain until the view is closed. It is the
 // spinner's own frame interval wide, and the cost is a spinner that spins fast.
 func (m Model) spinnerTickIfIdle() tea.Cmd {
-	if len(m.scanningPaths) > 0 || len(m.syncingPaths) > 0 {
+	if m.anyBusy() {
 		return nil
 	}
 	return m.spinner.Tick
@@ -402,6 +403,11 @@ func (m Model) startDelete() (tea.Model, tea.Cmd) {
 	if !ok {
 		return m, nil
 	}
+	// Refused before the modal rather than after it: asking the question and
+	// then declining the answer is the one order that wastes the user's time.
+	if m.busy(entry.Path) {
+		return m, m.footer.Warn(busyMessage)
+	}

 	m.pendingEntry = &entry
 	m.mode = ModeConfirmingDelete
@@ -477,7 +483,20 @@ func (m Model) handleConfirmDelete() (tea.Model, tea.Cmd) {
 	if m.pendingEntry == nil {
 		return m, nil
 	}
-	return m, m.deleteEntry(m.pendingEntry.Path)
+	path := m.pendingEntry.Path
+	// Checked again here, not only in startDelete: a batch sync marks its
+	// repositories from a Cmd, so one can take this path while the
+	// confirmation is on screen. This is where the irreversible call is
+	// issued, so this is where the answer has to be current.
+	if m.busy(path) {
+		return m, m.footer.Warn(busyMessage)
+	}
+
+	tick := m.spinnerTickIfIdle()
+	m.deletingPaths[path] = true
+	m.footer.Clear()
+	m.refreshRows()
+	return m, tea.Batch(tick, m.deleteEntry(path))
 }

 // handleWorkspaceCreated handles the result of workspace creation
@@ -491,7 +510,12 @@ func (m Model) handleWorkspaceCreated(msg WorkspaceCreatedMsg) (tea.Model, tea.C

 // handleEntryDeleted handles the result of entry deletion
 func (m Model) handleEntryDeleted(msg EntryDeletedMsg) (tea.Model, tea.Cmd) {
+	// Cleared on every outcome, failures included: a marker left behind holds
+	// the path against every other action for the life of the view.
+	delete(m.deletingPaths, msg.Path)
+
 	if msg.Error != nil {
+		log.Printf("ERROR [workspaces] delete %s: %v", msg.Path, msg.Error)
 		m.error = msg.Error.Error()
 		return m, nil
 	}
